import{_ as e,o as n,c as o,a2 as t}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Ataques dirigidos y Anatomy","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/targeting-and-anatomy.md","filePath":"es/guide/combat/targeting-and-anatomy.md"}'),i={name:"es/guide/combat/targeting-and-anatomy.md"};function r(s,a,d,l,c,u){return n(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="targeted-attacks-and-anatomy" tabindex="-1">Ataques dirigidos y Anatomy <a class="header-anchor" href="#targeted-attacks-and-anatomy" aria-label="Enlace permanente a &quot;Ataques dirigidos y Anatomy&quot;">​</a></h1><ul><li><strong>Estado del diseño:</strong> Aceptado para la dirección de apuntado opcional y Anatomy acotada; Propuesto para interacciones más ricas.</li><li><strong>Implementación:</strong> Anatomy cualitativa está integrada; el apuntado elegido por el jugador está aplazado.</li><li><strong>Disponibilidad:</strong> aquí no se establece ningún comportamiento nuevo en vivo; no se ha inspeccionado la configuración actual.</li><li><strong>Verificación:</strong> documentación revisada el 2026-10-08; sin nueva prueba de juego. El alcance de la evidencia existente figura en <a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">estado del combate</a>.</li></ul><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Anatomy ofrece información cualitativa acotada sobre el estado, no certeza numérica oculta.</li><li>La región corporal solicitada expresa intención; el servidor resuelve el resultado real.</li><li>Las interacciones más ricas de apuntado e información siguen siendo propuestas; apuntar no concede un golpe extra gratuito.</li></ul><h2 id="information-helps-you-choose" tabindex="-1">La información ayuda a elegir <a class="header-anchor" href="#information-helps-you-choose" aria-label="Enlace permanente a &quot;La información ayuda a elegir&quot;">​</a></h2><p>El experimento actual y acotado de Anatomy puede informar del estado cualitativo de las siete regiones tras una evaluación exitosa. No revela la integridad exacta, los valores de trauma ni las probabilidades ocultas de apuntado. Los diagnósticos privilegiados del Lab son independientes de lo que sabe el personaje.</p><h2 id="a-choice-is-an-attempt" tabindex="-1">Elegir es intentar <a class="header-anchor" href="#a-choice-is-an-attempt" aria-label="Enlace permanente a &quot;Elegir es intentar&quot;">​</a></h2><p>Elegir un brazo debería expresar intención, no garantizar permanentemente que cada golpe impacte allí. El servidor sigue resolviendo si se produce un ataque, si acierta y dónde impacta. El apuntado opcional debe coexistir con los ataques automáticos ordinarios; seleccionar una región no concede un golpe extra gratuito.</p><p>El futuro apuntado puede depender de oportunidades, posición, arma, ejecución, habilidad del personaje, movimiento del defensor, información disponible y fatiga. Anatomy podría apoyar Healing y los conocimientos de caza y desuello, mientras Tactics ayuda a interpretar oportunidades y Arms Lore ayuda a interpretar el equipo. Estas ampliaciones no aumentan automáticamente la información revelada actualmente.</p><p><a href="/Syrolands-Public/es/game-design/combat/targeting.html">Especificación completa de apuntado</a> · <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">Información de Anatomy con estado Aceptado</a> · <a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">Estado del combate</a>.</p><p><a href="/Syrolands-Public/es/guide/combat/overview.html">Volver al resumen de combate</a></p>',11)])])}const g=e(i,[["render",r]]);export{p as __pageData,g as default};
